"""Build the complete Week 3 unit. Existing response IDs and option tokens stay stable."""
from pathlib import Path
from html import escape
import json,os

ROOT=Path(__file__).resolve().parents[1]
NAV=[('Reading','readings/week3_reading.html'),('Explorer','demos/center_spread.html'),('Laboratory','labs/week3_lab.html'),('Filling machines','applications/week3_application.html'),('Attention','applications/week3_ai.html'),('Discussion','discussions/week3_discussion.html')]
from activity_editorial import streamline_activity_html

from reading_editorial import streamline_reading_html

def write(path,text):
 text=streamline_activity_html(str(path),text)
 text=streamline_reading_html(str(path),text)
 p=ROOT/path;t=p.with_suffix(p.suffix+'.tmp')
 with t.open('w') as f:f.write(text);f.flush();os.fsync(f.fileno())
 os.replace(t,p)
def figure(name,alt,caption):return f'<figure class="figure"><img src="../assets/week3/{name}.svg" alt="{escape(alt,quote=True)}" loading="lazy"><figcaption>{caption}</figcaption></figure>'
def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+str(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def quick(q,a):return '<div class="quick-check"><p>'+q+'</p><details><summary>Compare your reasoning</summary><p>'+a+'</p></details></div>'
def num(id,label,ans,hint,tol=.001):return f'<div class="question"><label for="{id}">{label}</label><input id="{id}" type="text" inputmode="decimal" autocomplete="off" data-answer="{ans}" data-tolerance="{tol}" data-hint="{escape(hint,quote=True)}" aria-describedby="fb-{id}"><span class="field-feedback" id="fb-{id}" aria-live="polite"></span></div>'
def select(id,label,opts,ans,hint):return f'<div class="question"><label for="{id}">{label}</label><select id="{id}" data-answer="{ans}" data-hint="{escape(hint,quote=True)}" aria-describedby="fb-{id}"><option value="">Choose a response…</option>'+''.join(f'<option value="{v}">{escape(t)}</option>' for v,t in opts)+f'</select><span class="field-feedback" id="fb-{id}" aria-live="polite"></span></div>'
def written(id,label):return f'<div class="question"><label for="{id}">{label}</label><textarea id="{id}" rows="5" data-save></textarea></div>'
def check():return '<div class="actions"><button type="button" data-check>Check this section</button></div><p class="section-feedback" aria-live="polite"></p>'
def progress():return '<div class="progress"><span id="progressText">0 sections checked</span><div class="progress-track" aria-hidden="true"><div class="progress-fill" id="progressFill"></div></div></div>'
def page(path,kind,title,lead,body,tags,store=None,legacy=None,nextlink=None):
 nav=''.join(f'<a href="../{url}"'+(' aria-current="page"' if url==path else '')+'>'+label+'</a>' for label,url in NAV)
 attrs=f' data-answer-store="{store}"'+(f' data-legacy-store="{legacy}"' if legacy else '') if store else ''
 end='<div class="student-bar"><div><label for="studentName">Your name for the printed copy</label><input id="studentName" autocomplete="name"></div><button type="button" data-print-work>Print / save completed work</button><div><p id="saveStatus" class="small save-status" aria-live="polite"></p><p id="printStatus" class="small" role="status"></p></div></div>' if store else '<div class="actions no-print"><button type="button" data-print-page>Print this page</button></div>'
 if nextlink:end+=f'<div class="next"><a href="../index.html">← Course home</a><a href="../{nextlink[1]}">{nextlink[0]} →</a></div>'
 s='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+f'<meta name="description" content="{escape(lead,quote=True)}"><title>Week 3 {kind} — {escape(title)} | Math in Society</title>'+r'''
<link rel="stylesheet" href="../assets/week3/week3.css"><script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']}};</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><script defer src="../assets/week3/week3.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a href="../index.html">← MATH&amp; 107 · Math in Society</a><span>Centralia College · Dr Lee</span></header>'''+f'<nav class="unit-nav" aria-label="Week 3 materials">{nav}</nav><main class="wrap" id="main"{attrs}><header class="hero"><div class="eyebrow">Week 3 / {kind}</div><h1>{title}</h1><p class="lead">{lead}</p></header>'+('<p class="print-name" id="printName"></p>' if store else '')+body+end+'<footer class="footer"><span>MATH&amp; 107 · Center and Spread</span><a href="../readings/Math107_Chapter_03.pdf">Illustrated chapter, practice, and solutions ↗</a></footer></main></body></html>\n'
 write(path,s)

def section(id,title,body):return f'<section class="card" id="{id}"><h2>{title}</h2>{body}</section>'
SCHEMA=json.loads((ROOT/'scripts/week3_response_contracts.json').read_text())
def oldselect(file,id,label,answer,hint):
 field=next(x for x in SCHEMA[file] if x['attrs'].get('id')==id)
 return select(id,label,[(v,t) for v,t in field['options'] if v],answer,hint)

sections=[]
sections.append(('data','What are the numbers about?',r'''<p>A list of measurements is a <em>data set</em>. Each number describes an observation: perhaps one day’s waiting time or the amount in one bottle. Before calculating, ask what was measured, which units were used, and who or what the list describes.</p><p>Week 2 organized observations with counts and graphs. Week 3 asks how to summarize those observations. We need both a <em>center</em>, describing where values tend to sit, and a <em>spread</em>, describing how much they vary.</p><div class="example"><h3>The same average can describe different experiences</h3><p>One route to work takes 24, 25, and 26 minutes. Another takes 15, 25, and 35 minutes. Both average 25 minutes. The second route’s average does not tell you that some trips take much longer. If arriving on time matters, you will want to know about that variation.</p></div><p>Keep the measurements comparable. Combining minutes with hours without converting them first gives a meaningless average. A number describing one group may also tell us little about a different group.</p>'''+quick('What is missing from “The average was 25”?','We need to know what was measured, its units, which observations were included, and how much they varied. An average is a summary of a specified set of measurements.')))
sections.append(('mean','The mean: share the total equally',r'''<p>Add the values and divide by how many there are. This gives the <em>mean</em>, often called the average. Imagine sharing the total equally among all the observations.</p><div class="formula">\[\bar x=\frac{\text{sum of the values}}{\text{number of values}}=\frac{x_1+x_2+\cdots+x_n}{n}.\]</div><p>The symbol \(\bar x\) is read “x-bar.” The letter n counts the observations. The labels \(x_1,x_2,\ldots\) mean the first value, second value, and so on; the small numbers are labels, not powers.</p>'''+figure('mean-sharing','Five study-time observations of 2, 3, 3, 5, and 7 hours total 20. Sharing that same total equally gives five values of 4 hours.','The mean preserves the total: number of observations × mean = original total.')+r'''<div class="example"><h3>A mean does not have to appear in the list</h3><p>For 2, 3, 3, 5, and 7 hours, the total is 20 and the mean is 20 ÷ 5 = 4 hours. Nobody reported exactly 4 hours. The mean describes the whole list; it is not necessarily one person’s result.</p><p>You can reverse the calculation. If four values have mean 12, their total must be 4 × 12 = 48. If three are 9, 11, and 13, the missing value is 48 − 33 = 15.</p></div>'''+quick('The values are 4, 6, and 8 minutes. Find the mean, then recover their total from the mean.','The mean is (4 + 6 + 8)/3 = 6 minutes. Three observations × 6 minutes = 18 minutes, the original total.')))
sections.append(('median','The median: find the middle after ordering',r'''<p>Put the observations in order before finding the <em>median</em>. With an odd number of values, choose the middle position. With an even number, average the two middle values.</p>'''+figure('median-positions','In five ordered values, the median occupies position three. In six ordered values, positions three and four supply the two values to average.','Count positions in the ordered list. The middle of the list is not necessarily halfway between the smallest and largest measurements.')+r'''<div class="example"><h3>Sort first</h3><p>The values 9, 2, 4, 4, 7, and 5 become 2, 4, 4, 5, 7, 9. There are six observations. Positions 3 and 4 contain 4 and 5, so the median is (4 + 5)/2 = 4.5.</p></div><p>Repeated values matter. In 1, 2, 2, 2, 9, the median is 2. There are not equal numbers <em>strictly</em> below and above it because several observations equal it. The ordered-position procedure still works.</p><p>The median depends on the middle of the ordering. Making an already largest value still larger often leaves the median unchanged. Removing an observation can change the middle positions, so the median is not guaranteed to stay fixed after every change.</p>'''+quick('Find the median of 3, 8, 1, and 6.','Sort to get 1, 3, 6, 8. The median is (3 + 6)/2 = 4.5. Averaging the endpoints would give the same answer here by coincidence; the procedure uses the two middle positions.')))
sections.append(('mode','The mode: count repeated values',r'''<p>The <em>mode</em> is a most frequently occurring value. A frequency table makes the count visible. There can be several tied modes.</p>'''+figure('mode-counts','The data 2, 4, 4, 6, 6, and 8 have tied modes 4 and 6. The data 10, 20, 30, and 40 have no repeated value.','For this course, report “no mode” when every observed value appears once. A tie among repeated values can give more than one mode.')+r'''<p>Mean, median, and mode answer different questions. The mean shares the total; the median finds the middle; the mode finds a most common value. They can agree, but they do not have to.</p><div class="example"><h3>Use the question to choose the summary</h3><p>A shop planning its most commonly requested size might care about the mode. To divide a total cost equally, the mean answers the question. To describe a middle amount when a few amounts are unusually large, the median may be more helpful.</p></div>'''+quick('What are the modes of 1, 1, 2, 3, and 3?','Both 1 and 3 occur twice, more often than 2. The modes are 1 and 3; averaging those two modes would answer a different question.')))
sections.append(('range','The range: measure the full width',r'''<p>The <em>range</em> is the maximum minus the minimum. It has the same units as the observations.</p><div class="formula">\[\text{range}=\text{largest value}-\text{smallest value}.\]</div><div class="example"><h3>Watch the subtraction sign</h3><p>For −3, 1, and 4 degrees, the range is 4 − (−3) = 7 degrees. For 8, 9, 10, 11, 12, the range is 12 − 8 = 4. For 2, 6, 10, 14, 18, it is 18 − 2 = 16. Those last two lists both have mean 10.</p></div><p>The range uses only the two extreme observations. It does not tell you where the remaining values lie. Two lists can therefore have the same mean and the same range while distributing their observations differently.</p>'''+figure('same-range','Two five-value data sets have mean 5, minimum 0, and maximum 10. In the first, most values lie near the middle; in the second, most lie at the endpoints.','Both ranges are 10. Looking at the observations reveals information the two endpoints miss.')+quick('A data set has minimum 7 and range 18. What is its maximum?','Maximum − 7 = 18, so maximum = 25. Range describes a difference, not the largest value by itself.')))
sections.append(('deviations','Distances from the mean',r'''<p>A <em>deviation</em> is an observation minus the mean. A value below the mean has a negative deviation; one above it has a positive deviation.</p>'''+figure('signed-deviations','For observations 2, 4, 4, and 6, the mean is 4. The deviations are minus 2, zero, zero, and plus 2.','The signs locate values relative to the mean. Opposite signed deviations can cancel even when the measurements vary.')+r'''<p>For 2, 4, 4, 6, the deviations add to −2 + 0 + 0 + 2 = 0. The zero does not mean there is no variation. It means the mean is a balance point: the signed departures below and above it cancel.</p><p>Simply averaging those signed deviations would always give zero, apart from rounding. To describe spread, we need a calculation in which departures cannot cancel each other.</p>'''+quick('For 1, 3, and 5, find the mean and the three deviations.','The mean is 3. The deviations are −2, 0, and +2, which sum to zero. The observations are still different.')))
sections.append(('sample-sd','Sample standard deviation, one step at a time',r'''<p>The <em>sample standard deviation</em>, written s, describes spread around the mean using every observation. It is useful to think of it as a scale for distances from the mean. It is not calculated by averaging the ordinary distances.</p><p>Square each deviation so opposite signs cannot cancel. Add those squares. For a sample, divide by n − 1 to obtain the <em>sample variance</em>. Finally, take the square root to return to the original units.</p><div class="formula">\[s=\sqrt{\frac{(x_1-\bar x)^2+\cdots+(x_n-\bar x)^2}{n-1}}.\]</div><p>The compact symbol \(\sum\) sometimes replaces the long addition. It means “add these terms.” Work down the columns of a table before trying to do the whole formula at once.</p>'''+table(['Value x','Deviation x − 4','Squared deviation'],[['2','−2','4'],['4','0','0'],['4','0','0'],['6','2','4'],['Total','0','8']])+r'''<div class="example"><h3>Complete the last two steps</h3><p>There are four observations, so n − 1 = 3. The sample variance is 8/3 ≈ 2.67 squared units. The sample standard deviation is \(\sqrt{8/3}\approx1.63\) original units. Keep the fraction until the last step; rounding the variance too early can change the answer.</p></div>'''+figure('squares-and-units','The deviations minus 2 and plus 2 both produce squares of area 4. Together with two zero deviations, they give a squared-deviation sum of 8.','Squaring changes the units. The final square root makes standard deviation comparable with the original measurements.')+r'''<p>Why n − 1? We have already used the sample to find its mean. Once that mean and all but one deviation are known, the last deviation is fixed by their sum being zero. The sample-variance rule allows for that lost freedom. Its statistical justification concerns estimating variation in a larger population; you do not need that proof to follow the calculation here.</p><p>Some calculators offer both a sample SD and a population SD. A population calculation divides by the full count when the list is the entire population being described. These assigned calculations use the <em>sample</em> formula and n − 1. At least two observations are needed. With two or more identical values, s = 0.</p>'''+quick('For 1, 3, and 5, the squared deviations total 8. Find the sample variance and sample standard deviation.','There are three observations, so divide by 3 − 1 = 2. The variance is 4 squared units, and s = √4 = 2 original units.')))
sections.append(('comparison','Look at the graph as well as the summaries',r'''<p>Compare centers first, then spreads, while keeping the setting and units in view. A larger standard deviation means greater spread around that mean. It does not automatically mean better performance.</p>'''+figure('same-mean-spread','Two five-value samples both have mean 50. One clusters at 49 to 51, while the other spans 30 to 70 on the same horizontal scale.','The same axis makes the difference visible. Range and sample standard deviation both show that the second sample is more spread out.')+r'''<p>Now consider five weekly amounts: 10, 12, 13, 14, and 101 dollars. Their mean is 30 dollars; their median is 13 dollars. The mean correctly shares the full total of 150 dollars. The median better describes the middle of these particular weekly amounts.</p>'''+figure('outlier-center','Changing the final amount from 101 to 16 changes the mean from 30 to 13. The median stays at 13, while the range drops from 91 to 6.','An unusually distant value can strongly change the mean, range, and standard deviation. The median is often less sensitive.')+r'''<p>A value far from the others is worth investigating. It could be a recording error or a real unusual event. Comparing summaries with and without it shows its influence; it does not by itself justify deleting the observation.</p><p>The range is <em>not</em> resistant to extreme values. Using a median alongside a range does not make the range resistant. For this course, calculate the requested measures and explain what each reveals. Other courses may introduce measures such as the interquartile range that focus on the middle part of the data.</p><p>Histograms group observations into intervals. A bar’s height counts observations in that interval. The tallest bar identifies a most common interval, not necessarily the location of the mean or median.</p>'''+figure('histogram-center','Fifty hypothetical scores out of 110 have mean 81 and median 85. The tallest interval, 70 to below 80, contains 14 scores.','Here the raw scores are 55, 65, 75, 85, 95, and 105, occurring 3, 7, 14, 13, 9, and 4 times. The tallest bin contains 28% of the sample, not a majority.')+quick('If a sample has one very large value, is the range protected from its effect by reporting the median?','No. The median and range are separate calculations. The median can stay nearly fixed while the maximum and therefore the range change greatly.')))
sections.append(('weighted','Weighted averages: unequal shares',r'''<p>In an ordinary mean, each observation receives the same share of the total weight. A <em>weighted average</em> allows different shares. Multiply each value by its weight, then add. For the form used here, the weights are nonnegative and sum to 1.</p><div class="formula">\[\text{weighted average}=w_1x_1+\cdots+w_nx_n,\qquad w_1+\cdots+w_n=1.\]</div><div class="example"><h3>Two scores with different weights</h3><p>Scores of 70 and 90 have ordinary mean 80. If the first counts for 25% and the second for 75%, the weighted result is 0.25(70) + 0.75(90) = 17.5 + 67.5 = 85. Convert the percentages to decimal weights before multiplying.</p></div><p>With nonnegative weights summing to 1, the result stays between the smallest and largest values. Larger weight means a value has more influence on the combined result. It does not turn the weight into a statement that the value is correct.</p><p>The <a href="../applications/week3_ai.html">attention application</a> uses this same operation to combine numerical information. Work the familiar weighted average before reading about its role in a model.</p>'''+quick('Scores of 60 and 80 receive weights 0.25 and 0.75. Find the weighted average and check its bounds.','The result is 0.25(60) + 0.75(80) = 15 + 60 = 75. It lies between 60 and 80 and is closer to the more heavily weighted value 80.')))
sections.append(('changes','Moving or rescaling every value',r'''<p>If you add the same number to every observation, all the points move together. Their mean and median move by that number, but the distances between points do not change. Range and standard deviation stay the same.</p><p>If you multiply every observation by 2, the distances double too. The mean, median, range, and standard deviation all double. Multiplication by a negative number also reverses order; spread changes by the magnitude of the multiplier and remains nonnegative.</p>'''+figure('shift-and-scale','Starting values 2, 4, 4, 6 have mean 4. Adding 10 gives mean 14 with unchanged standard deviation. Multiplying the starting values by 2 gives mean 8 and twice the standard deviation.','Moving the whole data set changes its location. Stretching it changes its spread. Keep the units and transformation clear.')+quick('A sample has mean 20 and sample SD 3. Add 5 to every value. What are the new mean and sample SD?','The mean becomes 25; the sample SD stays 3. Each value and the mean moved by the same 5, leaving every deviation unchanged.')))
sections.append(('meaning','What does the result tell us?',r'''<p>Write the result with its units and a sentence about the data. “The five test bottles averaged 250 mL, with sample SD about 0.71 mL” tells us more than two unlabeled calculator outputs.</p>'''+table(['Question','Useful calculation','What to keep in view'],[['What would each share be if the total were equal?','Mean','Every value affects the total'],['What is the middle ordered value?','Median','Sort first; use both middle values when needed'],['Which value repeats most often?','Mode','Ties and no repeated values are possible'],['How far apart are the extremes?','Range','It uses only the endpoints'],['How much do values vary around the mean?','Sample standard deviation','Use all values and the n − 1 rule here']])+r'''<p>A summary describes the observations we have. Whether those observations represent a larger group depends on how they were selected and measured. A narrow spread does not establish that the sample came from the right population or that the measuring instrument was accurate.</p><p>Week 4 introduces normal models and intervals for population quantities. Here we are learning to describe observed variation. A standard deviation alone does not prove that a data set has a bell shape or tell us a tail percentage.</p>'''+quick('Two filling machines average the target amount. Does that settle which is more consistent?','No. Compare their observed ranges and sample SDs, inspect the values, and apply the stated tolerance rule. Equal means can conceal very different variation.')+r'''<p class="reading-note">References: NIST’s <a href="https://www.itl.nist.gov/div898/handbook/eda/section3/eda351.htm">measures of location</a> and <a href="https://www.itl.nist.gov/div898/handbook/eda/section3/eda356.htm">measures of scale</a>. Numerical examples in this unit are hypothetical.</p>'''))

reading=r'''<section class="card"><h2>One typical value cannot tell the whole story</h2><p>Two routes can have the same average travel time while one is much less predictable. Two machines can average the right fill amount while one varies widely from bottle to bottle. We need to describe both the center and the spread.</p><p>The methods here build on Week 2’s observations, frequency tables, and graphs. Read each calculation as an answer to a question about a particular set of measurements. Work through the examples before using the <a href="../demos/center_spread.html">explorer</a> and <a href="../labs/week3_lab.html">laboratory</a>. The <a href="Math107_Chapter_03.pdf">illustrated chapter</a> adds exercises and complete solutions.</p></section><nav class="card toc" aria-label="In this reading"><h2>Contents</h2><ol>'''+''.join(f'<li><a href="#{id}">{title}</a></li>' for id,title,body in sections)+'</ol></nav>'+''.join(section(*s) for s in sections)+r'''<section class="card"><h2>Week 3 activities</h2><ul><li><a href="../demos/center_spread.html">Explorer: enter data, compare graphs, and follow the standard-deviation table</a></li><li><a href="../labs/week3_lab.html">Laboratory: center, range, sample standard deviation, and unusual values</a></li><li><a href="../applications/week3_application.html">Application: compare two filling machines</a></li><li><a href="../applications/week3_ai.html">Attention: a weighted-average application</a></li><li><a href="../applications/ai_week3.html">Additional attention and spread practice</a></li><li><a href="../discussions/week3_discussion.html">Discussion: what an average misses in your own example</a></li></ul></section>'''
page('readings/week3_reading.html','Reading','Center, spread, and the story in the data','Use a graph and a few carefully chosen numbers to describe where observations sit, how much they vary, and what those summaries mean.',reading,['Mean, median, mode','Range and sample SD','Weighted averages'],nextlink=('Open the center and spread explorer','demos/center_spread.html'))

explorer=r'''<section class="card"><h2>Enter observations, then look at both center and spread</h2><p>Load a preset or enter values separated by commas, spaces, or new lines. Each value is one observation. The calculator uses the sample standard deviation, dividing squared deviations by n − 1. With one observation, it can report a mean but cannot calculate a sample SD.</p><div class="actions"><button type="button" data-preset="tight">Same mean: tight</button><button type="button" data-preset="wide">Same mean: wide</button><button type="button" data-preset="outlier">Add an outlier</button><button type="button" data-preset="complaints">Complaint data</button></div><div class="data-controls"><label for="data">Your data (use the same measurement units)</label><textarea id="data" rows="3">50, 51, 50, 49, 50</textarea></div><div class="actions"><button type="button" id="go">Analyze</button><span class="small">Ctrl + Enter also analyzes the data.</span></div><p id="dataError" class="chart-error" role="status"></p><div id="dataResults"><div class="summary-grid"><div class="stat"><span>Number of observations n</span><output id="count"></output></div><div class="stat"><span>Mean</span><output id="mean"></output></div><div class="stat"><span>Median</span><output id="median"></output></div><div class="stat"><span>Mode(s)</span><output id="mode"></output></div><div class="stat"><span>Range</span><output id="range"></output></div><div class="stat"><span>Sample standard deviation s</span><output id="sd"></output></div></div><div class="controls"><div><label for="plotKind">Graph</label><select id="plotKind"><option value="dots">Dotplot: each point is one observation</option><option value="histogram">Histogram: count values in intervals</option></select></div><div><label for="scaleMode">Horizontal scale</label><select id="scaleMode"><option value="fixed">Compare on the same 0–100 window</option><option value="fit">Fit the window to these data</option></select></div><div><label for="binCount">Histogram intervals</label><input id="binCount" type="number" min="2" max="20" step="1" value="6"></div></div><div class="chart" id="c">'''+figure('same-mean-spread','Two samples have mean 50 but different spreads on the same horizontal scale.','Enable JavaScript to graph your own data.')+r'''</div><p id="plotNote" class="reading-note"></p><p class="readout" id="note" aria-live="polite"></p><details><summary>Counts and histogram intervals</summary><h3>Exact observed values</h3><div class="table-wrap trace" id="frequencyTable"></div><h3>Histogram counts</h3><p>The left endpoint is included. The right endpoint is excluded except in the final interval, which includes the largest endpoint.</p><div class="table-wrap" id="binTable"></div></details><details><summary>Follow the sample standard deviation</summary><p>The mean is subtracted from each observation. The final column squares that deviation. Add that column, divide by n − 1, then take the square root.</p><div class="table-wrap trace" id="deviationTable"></div><p id="sdCalculation" class="worked-sum"></p></details></div></section>
<section class="card"><h2>Change just one value</h2><p>The first six values stay at 5, 6, 7, 8, 9, and 10. Only the final value changes. Predict which summaries will move before adjusting it.</p><div class="controls"><div><label for="outlierValue">Final value: <output id="outlierReadout">85</output></label><input id="outlierValue" type="range" min="11" max="150" step="1" value="85"></div></div><p id="outlierSummary" class="readout" aria-live="polite"></p><div class="chart" id="outlierPlot"></div><div class="table-wrap" id="outlierTable"></div><p>Changing a value here is an experiment about the summaries. In an actual study, investigate an unusual observation before deciding what to do with it.</p></section>
<section class="card"><h2>Questions to investigate</h2><ol><li>Compare the two “same mean” presets on the fixed scale. What changes even though both means are 50?</li><li>Switch to a fitted scale. How could separately fitted graphs make spreads look more alike than they are?</li><li>Load the complaint data, fit the scale, and try different histogram intervals. The observations do not change; what happens to the picture?</li><li>Enter three identical values. Explain the range and sample SD. Then try a single observation.</li><li>Change the final value in the second experiment. Use the ordered list to explain why the median stays at 8.</li></ol><p><a href="../labs/week3_lab.html">Continue with the laboratory</a>, where each numerical response receives feedback.</p></section>'''
page('demos/center_spread.html','Explorer','Center and spread explorer','Compare numerical summaries with a graph, inspect the standard-deviation steps, and see what changes when one observation moves.',explorer,['Observed data','Common graph scales','Calculation tables'],nextlink=('Open the laboratory','labs/week3_lab.html'))

lf='labs/week3_lab.html';ls=lambda *a:oldselect(lf,*a)
lab=r'''<section class="card"><h2>Center and spread together</h2><p>First ask where the observations sit, then ask how much they vary. Work through the examples before entering your answers. The <a href="../readings/week3_reading.html">reading</a> explains each measure, and the <a href="../demos/center_spread.html">explorer</a> shows the same quantities in a graph and a table.</p><p>Use the sample SD formula with n − 1. Keep extra precision until your final answer; two decimal places are enough for the SD questions here. Responses save in this browser. Enter your name at the bottom when you print your completed work for submission in Canvas.</p></section>'''+progress()+r'''
<section class="card" id="part1" data-check-group="1"><h2>Part 1. Customer complaints</h2><div class="example"><h3>Three centers can differ</h3><p>For 1, 2, 2, 3, 12, the mean is 20/5 = 4. The median is 2 and the mode is 2. Changing the largest value from 12 to 4 gives mean 2.4, while the median and mode stay at 2.</p></div><p>A store recorded the number of customer complaints received on ten days:</p><p class="dataset">3, 0, 5, 2, 1, 4, 2, 8, 2, 3.</p><div class="grid three">'''+num('cMean','Mean',3,'Add all ten values and divide by 10.',.02)+num('cMedian','Median',2.5,'Sort the ten values, then average positions 5 and 6.',.02)+num('cMode','Mode',2,'Count how often each value occurs.',.02)+r'''</div><p>For the comparison below, remove the value 8. There are now nine observations.</p><div class="grid three">'''+num('cMean2','New mean',22/9,'The remaining total is 22; divide by nine, not ten.',.02)+num('cMedian2','New median',2,'Find position 5 in the ordered nine-value list.',.02)+num('cMode2','New mode',2,'Count the remaining repeated values.',.02)+r'''</div><div class="grid">'''+ls('meanEffect','The mean','down','Compare the two calculated means.')+ls('modeEffect','The mode','same','The most frequent value is still the same.')+r'''</div>'''+written('complaintReason','Explain why the mean changes more here. What would you ask about the eight-complaint day before deciding whether to exclude it in a real report?')+check()+r'''</section>
<section class="card" id="part2" data-check-group="2"><h2>Part 2. Totals, missing values, and range</h2><div class="example"><h3>Recover a total</h3><p>Four scores with mean 75 total 4 × 75 = 300. If three scores are 70, 80, and 72, their sum is 222, leaving 78 for the missing score. For 4, 7, 9, 14, the range is 14 − 4 = 10.</p></div><h3>A missing test score</h3><p>Seven students have mean score 80. Six scores are 72, 78, 84, 80, 76, and 88.</p><div class="grid">'''+num('totalSeven','Total points for all seven students',560,'Multiply seven observations by the mean 80.',.02)+num('missingScore',"Seventh student’s score",82,'Subtract the sum of the six known scores from the total.',.02)+r'''</div><p>A data set has range 40 and minimum 15.</p>'''+num('maxFromRange','Maximum value',55,'Maximum minus 15 is 40.',.02)+r'''<h3>Two delivery drivers</h3>'''+table(['','Day 1','Day 2','Day 3','Day 4','Day 5'],[['Driver A',12,14,11,13,15],['Driver B',8,18,10,16,13]])+r'''<div class="grid">'''+num('meanA','Mean A',13,'The five counts total 65.',.02)+num('rangeA','Range A',4,'Subtract 11 from 15.',.02)+num('meanB','Mean B',13,'Add all five Driver B counts, then divide by five.',.02)+num('rangeB','Range B',10,'Subtract 8 from 18.',.02)+r'''</div>'''+ls('driverConsistent','More consistent driver','A','For this comparison, smaller range means less observed variation.')+written('driverReason','The drivers have the same average. Explain what the range adds, using the daily counts.')+check()+r'''</section>
<section class="card" id="part3" data-check-group="3"><h2>Part 3. Build a sample-SD table</h2><p>Use the data 3, 5, 5, 7. Work down one column at a time: subtract the mean, then square each deviation. A zero deviation is a real numerical answer.</p>'''+num('sdMean','Step 1: mean',5,'The four values total 20.',.02)+table(['Value x','Deviation x − mean','Squared deviation'],[[x,num('d'+str(i),'Deviation for observation '+str(i+1),d,'Subtract the mean 5; keep the sign.',.02),num('q'+str(i),'Squared deviation for observation '+str(i+1),d*d,'Square the signed deviation; a square is nonnegative.',.02)] for i,(x,d) in enumerate([(3,-2),(5,0),(5,0),(7,2)])])+r'''<div class="grid three">'''+num('sumSq','Sum of squared deviations',8,'Add 4 + 0 + 0 + 4.',.02)+num('varPop','Sample variance',8/3,'Divide the squared-deviation sum by n − 1 = 3.',.02)+num('sdVal','Sample standard deviation',(8/3)**.5,'Take the square root of 8/3. Round only at the end.',.02)+r'''</div>'''+figure('squares-and-units','Two deviations of magnitude 2 have squares of 4; the squared-deviation sum is 8 and the final square root returns to original units.','The variance and SD are different numbers, with different units.')+written('sdReason','Explain why adding the signed deviations would hide the spread, and why the final square root is needed.')+check()+r'''</section>
<section class="card" id="part4" data-check-group="4"><h2>Part 4. The same center, different spread</h2><p>Set A: 50, 51, 50, 49, 50. Set B: 30, 40, 50, 60, 70. Make a prediction about spread before calculating.</p>'''+ls('largerPredict','Which set should have the larger sample SD?','B','Compare how far the observations lie from 50.')+figure('same-mean-spread','Set A clusters from 49 to 51. Set B spans 30 to 70. Both have mean 50 and are plotted on the same axis.','Use the values and a shared scale to explain your prediction.')+r'''<div class="grid">'''+num('sameMeanA','Mean A',50,'The five values sum to 250.',.02)+num('sameSdA','Sample standard deviation A',.5**.5,'The squared deviations total 2. Divide by 4, then take the square root.',.02)+num('sameMeanB','Mean B',50,'The five values are balanced around 50.',.02)+num('sameSdB','Sample standard deviation B',250**.5,'The squared deviations total 1,000. Divide by 4, then take the square root.',.02)+r'''</div>'''+ls('moreConsistent','Which set is more consistent?','A','Smaller sample SD means the observed values stay closer to their mean.')+written('consistencyReason','Compare the samples in a sentence that includes both their centers and their spreads. Explain why the common axis matters.')+check()+r'''</section>
<section class="card" id="part5" data-check-group="5"><h2>Part 5. One unusually large value</h2><p>Use 5, 6, 7, 8, 9, 10, 85.</p><div class="grid three">'''+num('outMean','Mean',130/7,'The seven values total 130.',.02)+num('outMedian','Median',8,'The ordered list has seven observations; choose position 4.',.02)+num('outRange','Range',80,'Subtract the minimum 5 from the maximum 85.',.02)+r'''</div><div class="grid">'''+ls('bestCenter','Which statistic better represents a typical value here?','median','Six observations cluster from 5 to 10. Which center describes that middle?')+ls('outReason','Why is the mean so much larger?','outlier','The mean includes every value in its total.')+r'''</div><p>Replace 85 with 11, keeping seven observations.</p><div class="grid three">'''+num('cleanMean','New mean',8,'Add 5 through 11 and divide by seven.',.02)+num('cleanMedian','New median',8,'Choose the middle of the new ordered list.',.02)+num('cleanRange','New range',6,'Subtract 5 from 11.',.02)+r'''</div>'''+written('outlierReason','Explain which summaries changed and why. How could a real unusually large value still be important even if the median describes a typical observation better?')+check()+r'''<p>Check the numerical feedback and review your explanations before printing. The numerical checks do not grade your written reasoning.</p></section>'''
page(lf,'Laboratory','Center and spread','Use the mean, median, mode, range, and sample standard deviation to explain what a set of observations does—and does not—tell us.',lab,['Five investigations','Observed variation','Interpreting summaries'],store='math107_week3_lab_v4',legacy='math107_week3_lab_v3',nextlink=('Compare the filling machines','applications/week3_application.html'))

af='applications/week3_application.html';aps=lambda *a:oldselect(af,*a)
application=r'''<section class="card"><h2>The target and the test fills</h2><p>Two machines are set to fill bottles to 250 mL. Engineers sample five bottles from each. A machine should be near the target and reasonably consistent from bottle to bottle. These are different questions.</p>'''+table(['Machine','Bottle 1','Bottle 2','Bottle 3','Bottle 4','Bottle 5'],[['A',250,251,249,250,250],['B',245,255,248,253,249]])+r'''<p>The company’s rule for this test is that every sampled fill must lie from 246 through 254 mL, including the endpoints. This is a stated process rule, not a range calculated from the data.</p><div class="example"><h3>Center and consistency are different</h3><p>A sample of 98, 100, 102 averages 100 with range 4. A sample of 90, 100, 110 also averages 100 but has range 20. The shared average does not guarantee similar individual fills.</p></div></section>'''+progress()+r'''<section class="card" data-check-group="1"><h2>Calculate and compare</h2><p>Use the sample SD: subtract the sample mean, square, add, divide by 4, then take the square root.</p><div class="grid"><div><h3>Machine A</h3>'''+num('meanA','Mean A (mL)',250,'Add the five A fills and divide by five.',.02)+num('rangeA','Range A (mL)',2,'Subtract the smallest A fill from the largest.',.02)+num('sdA','Sample SD A (mL)',.5**.5,'The A squared deviations total 2. Divide by four and take the square root.',.02)+r'''</div><div><h3>Machine B</h3>'''+num('meanB','Mean B (mL)',250,'Add the five B fills and divide by five.',.02)+num('rangeB','Range B (mL)',10,'Subtract the smallest B fill from the largest.',.02)+num('sdB','Sample SD B (mL)',4,'The B squared deviations total 64. Divide by four and take the square root.',.02)+r'''</div></div>'''+aps('choice','Which machine is more consistent?','A','Compare the observed ranges and sample SDs.')+aps('spec','Which sample meets the rule that every test fill is 246–254 mL?','A','Check each individual fill, not just the two means.')+written('machineReason','Recommend a machine for this test. Use both the target and the observed spread, then explain the tolerance check.')+check()+r'''</section><section class="card"><h2>Read the result in context</h2>'''+figure('machine-comparison','Both five-bottle samples average 250 mL. A stays inside the shaded 246 to 254 band; B has test fills at 245 and 255 outside it.','The shaded band is the company’s acceptance rule. It is not a confidence interval or a normal-model percentage region.')+r'''<details><summary>Compare your calculations</summary><p>Both means are 250 mL. Machine A has range 2 mL and sample SD about 0.71 mL. Machine B has range 10 mL and sample SD 4 mL. A is more consistent in these observations and is the only sample with every fill inside the stated band.</p><p>Five observed bottles do not establish what every future bottle will contain. More measurements and information about how the sample was selected would help assess the process.</p></details>'''+written('machineLimits','What additional measurements or sampling information would help you judge whether this test represents the machine’s usual operation?')+r'''</section>'''
page(af,'Application','Choosing a filling machine','Compare center, bottle-to-bottle spread, and a stated acceptance rule using two five-bottle samples.',application,['Target versus spread','Sample standard deviation','Acceptance limits'],store='math107_week3_application_v4',legacy='math107_week3_application_v3',nextlink=('Explore weighted averages and attention','applications/week3_ai.html'))

aif='applications/week3_ai.html'
ai=r'''<section class="card"><h2>From an ordinary mean to unequal weights</h2><p>Imagine combining two scores. If both count equally, take their ordinary mean. If one counts more, a weighted average gives it a larger share of the result. This is the familiar calculation behind the small attention example here.</p><p>The four values 2, 5, 8, and 10 have ordinary mean (2 + 5 + 8 + 10)/4 = 6.25. Equal decimal weights give the same result: 0.25(2) + 0.25(5) + 0.25(8) + 0.25(10) = 6.25.</p></section><section class="card"><h2>Combine one numerical feature</h2><p>Suppose four tokens carry one numerical feature with values 2, 5, 8, and 10. A <em>token</em> is one of the pieces of text a model processes. In this example, the weights are 0.10, 0.20, 0.60, and 0.10. They are nonnegative and total 1.</p>'''+table(['Feature value','Weight','Product'],[[2,.10,.20],[5,.20,1.00],[8,.60,4.80],[10,.10,1.00]])+r'''<p>Add the products: 0.20 + 1.00 + 4.80 + 1.00 = 7.00. The combined feature is 7, compared with ordinary mean 6.25. The weight 0.60 gives the value 8 a particularly strong influence.</p>'''+figure('weighted-contributions','The weights 0.1, 0.2, 0.6, and 0.1 produce contributions 0.2, 1, 4.8, and 1 from feature values 2, 5, 8, and 10.','A weight is a share. A contribution is weight × value. Add contributions, not just weights, to obtain the combined feature.')+r'''<p>In transformer attention, a model computes context-dependent weights and combines value vectors. A vector is a list of numerical features. Each coordinate is combined by the weighted-sum operation shown here. Our single feature makes that arithmetic visible.</p></section><section class="card"><h2>Change the weights, keep the values</h2><label for="weightPreset">Weight choice</label><select id="weightPreset"><option value="given">Given weights: 0.10, 0.20, 0.60, 0.10</option><option value="equal">Equal weights: 0.25 each</option><option value="focus2">More weight on 2: 0.70, 0.10, 0.10, 0.10</option></select><p id="weightSummary" class="readout" aria-live="polite"></p><div class="chart" id="weightPlot"></div><div class="table-wrap" id="weightTable"></div><p>Predict which direction the result will move before changing the preset. Check that the weighted result stays between 2 and 10. A large weight shows influence in this combination; it does not show that the information is true.</p></section>'''+progress()+r'''<section class="card" data-check-group="1"><h2>Try the weighted calculation</h2><p>Use the given weights 0.10, 0.20, 0.60, and 0.10 for these questions, regardless of the explorer setting above.</p><div class="grid">'''+num('q1','Sum of the four given attention weights',1,'Add all four weights; a normalized total is 1.',.001)+num('q2','Weighted result for 2, 5, 8, and 10',7,'Multiply each value by its corresponding weight, then add.',.007)+num('q3','Result if every weight is 0.25',6.25,'Equal weights reproduce the ordinary mean.',.00625)+oldselect(aif,'q4','Why does the value 8 have especially strong influence?','It receives the largest weight, 0.60.','Compare the weight assigned to each feature value.')+r'''</div>'''+written('attentionReason','Explain the difference between a feature value, its weight, and its weighted contribution. Use one row from the table.')+check()+r'''</section><section class="card"><h2>What this picture includes</h2><p>The numbers here are assigned for practice. Real models learn transformations and use many features, heads, and layers. An attention weight alone is not a complete account of why a model produced an answer.</p><p>In a next-token generator, attention uses the text available so far. The <a href="ai_week3.html">additional practice</a> also shows a whole-sentence example; it explains why those two settings must be distinguished.</p><p>Week 8 will connect nonnegative weights adding to 1 with geometric mixtures. Here the central calculation is the weighted average.</p><p class="reading-note">Source: Vaswani and colleagues, <a href="https://arxiv.org/html/1706.03762v7">Attention Is All You Need</a>, especially Sections 3.2 and 3.2.3.</p></section>'''
page(aif,'AI Application','Attention as a weighted average','Start with a familiar average, give values unequal shares, and see how the combined result changes.',ai,['Equal and unequal weights','Numerical features','Interpreting influence'],store='math107_ai_module_3_v5',legacy='math107_ai_module_3_v4',nextlink=('Additional attention practice','applications/ai_week3.html'))

ef='applications/ai_week3.html';es=lambda *a:oldselect(ef,*a)
extra=r'''<section class="card"><h2>A whole sentence and a small set of weights</h2><p>Consider “The dog chased the ball because it rolled.” Number the words from 1 to 8. The word “it” is in position 7. Suppose a toy attention calculation combines information from these five positions:</p>'''+table(['Token','Position','Weight'],[['dog',2,.10],['chased',3,.05],['ball',5,.70],['because',6,.05],['rolled',8,.10]])+r'''<p>This is a <em>whole-sentence</em> illustration: all the words are already available. “Rolled” comes after “it.” A model generating text one token at a time could not use that future word while predicting it; such attention masks out future positions. The table’s numbers illustrate an unmasked combination, not that next-token situation.</p><p>The assigned weights do not establish what a real model would do with this sentence. They let us practice the weighted-average calculation.</p></section>'''+progress()+r'''<section class="card" data-check-group="1"><h2>1. Check the weights</h2>'''+num('q1','Sum of the five attention weights',1,'Add 0.10 + 0.05 + 0.70 + 0.05 + 0.10.')+check()+r'''</section><section class="card" data-check-group="2"><h2>2. Find the largest weight</h2>'''+es('q2','Which token receives the largest attention weight from “it”?','ball','Find the table’s largest weight, 0.70.')+check()+r'''</section><section class="card" data-check-group="3"><h2>3. Calculate a weighted position</h2><p>Use 0.10(2) + 0.05(3) + 0.70(5) + 0.05(6) + 0.10(8).</p>'''+num('q3','Weighted average position',4.95,'Multiply each listed position by its weight, then add.',.01)+written('positionMeaning','Explain why a weighted position can be a decimal even though the listed word positions are whole numbers.')+check()+r'''</section><section class="card">'''+figure('token-weights','The complete-sentence table places weight 0.70 on ball at position 5. The weighted average of the five positions is 4.95.','A weighted position describes this mixture of positions. It is not a fractional token or a token ID.')+r'''</section><section class="card" data-check-group="4"><h2>4. Blend a feature</h2><p>Four tokens carry feature values 10, 20, 30, and 40. Their corresponding weights are 0.10, 0.20, 0.60, and 0.10.</p>'''+num('q4','Weighted combination of the four feature values',29,'Add 0.10(10) + 0.20(20) + 0.60(30) + 0.10(40).')+check()+r'''</section><section class="card" data-check-group="5"><h2>5. The same center, different concentration</h2><p>Two toy heads focus on these five positions, treating the five listed observations equally:</p>'''+table(['Head','Positions'],[['A','4, 5, 5, 5, 6'],['B','1, 3, 5, 7, 9']])+r'''<div class="grid">'''+num('q5a','Mean position of Head A',5,'Add the five A positions and divide by five.')+num('q5b','Mean position of Head B',5,'Add the five B positions and divide by five.')+r'''</div>'''+es('q5c','More concentrated head','A','Compare the positions’ distances from their common mean, or their ranges.')+written('headReason','Explain what the two equal means miss. Use the actual positions or their ranges in your explanation.')+check()+r'''</section><section class="card">'''+figure('attention-spread','Head A’s positions cluster from 4 to 6, while Head B’s span 1 to 9. Both means are 5 on the same scale.','The summaries of center and spread remain separate questions, even in a numerical model of text.')+r'''<p class="reading-note">Source: <a href="https://arxiv.org/html/1706.03762v7">Attention Is All You Need</a>, Sections 3.2 and 3.2.3, for weighted value combinations and the distinction between encoder and masked decoder attention.</p></section>'''
page(ef,'AI Mathematics','Weighted positions and concentrated attention','Practice sums of weights, weighted feature values, and the difference between a common mean and a common spread.',extra,['Weights and positions','Whole-sentence example','Center versus concentration'],store='math107_ai_week3_v2',legacy='math107_ai_week3_v1',nextlink=('Open the personal-experience discussion','discussions/week3_discussion.html'))

def update_dashboard():
 p=ROOT/'index.html';s=p.read_text();start=s.index('const WEEKS = ')+len('const WEEKS = ');weeks,end=json.JSONDecoder().raw_decode(s[start:]);w=next(x for x in weeks if x['week']==3)
 w['summary']='Describe observations with center, spread, and a graph; explain the calculations behind the mean, median, mode, range, sample SD, and weighted averages.'
 w['reading'][0].update(title='Week 3 — Center, Spread, and the Story in the Data (HTML reading)',note='Explanations of notation, illustrated calculations, common-scale comparisons, unusual values, and short checks.')
 w['reading'][1].update(title='Week 3 — Center, Spread, and Weighted Averages (PDF)',note='Illustrated chapter with worked examples, exercises, review questions, and complete solutions.')
 w['demos'][0]['note']='Enter observations, compare dotplots and histograms, inspect calculation tables, and move one unusually large value.'
 w['weekly_lab']['note']='Five investigations with individual feedback, saved responses, written explanations, and named printing.'
 w['application'][0]['note']='Compare the five-bottle samples using center, sample SD, a shared graph, and the stated acceptance band.'
 w['application'][1]['note']='Work through equal and unequal weights, change a weight preset, and connect the arithmetic with numerical attention features.'
 s=s[:start]+json.dumps(weeks,ensure_ascii=False,separators=(',',':'))+s[start+end:];write('index.html',s)
update_dashboard()
print('Built six Week 3 resources; preserved all 61 graded responses, the discussion, and quiz contracts.')
